const ateliers = $input.all();
let optionsHTML = '';

ateliers.forEach(atelier => {
  // On ignore la ligne si le nom de l'atelier est vide (évite le "null")
  if (atelier.json['Nom de l\'atelier']) {

    // Nettoyage de la date pour un affichage lisible
    let dateBrute = atelier.json['Date et Heure'];
    let dateFormatee = dateBrute;
    try {
      const d = new Date(dateBrute);
      dateFormatee = d.toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
    } catch(e) {}

    optionsHTML += `<option value="${atelier.json.ID_Atelier}">${atelier.json['Nom de l\'atelier']} (${dateFormatee})</option>`;
  }
});

const html = `
<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Inscription - SkillsBoost</title>
    <style>
        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f0f2f5; padding: 40px; }
        .container { max-width: 500px; margin: 0 auto; background: white; padding: 40px; border-radius: 12px; box-shadow: 0 8px 24px rgba(0,0,0,0.08); }
        .header { text-align: center; margin-bottom: 30px; }
        .logo { font-size: 24px; font-weight: bold; color: #4f46e5; background: #e0e7ff; display: inline-block; padding: 8px 16px; border-radius: 50px; margin-bottom: 10px; }
        h2 { color: #1f2937; margin: 0; font-size: 22px; }
        label { font-weight: 600; color: #4b5563; display: block; margin-top: 20px; font-size: 14px; }
        input, select { width: 100%; padding: 12px; margin-top: 8px; border-radius: 6px; border: 1px solid #d1d5db; box-sizing: border-box; font-size: 14px; }
        input:focus, select:focus { outline: none; border-color: #4f46e5; box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1); }
        button { width: 100%; background-color: #4f46e5; color: white; padding: 14px; border: none; border-radius: 6px; margin-top: 30px; font-weight: bold; font-size: 16px; cursor: pointer; transition: background-color 0.2s; }
        button:hover { background-color: #4338ca; }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <div class="logo">🚀 SkillsBoost</div>
            <h2>Réservation d'Atelier</h2>
        </div>
        <form action="https://vps-308cfbf7.vps.ovh.net/webhook/formulaire-inscription" method="POST">
            <label for="email">Votre Adresse Email :</label>
            <input type="email" id="email" name="email" required placeholder="nom@exemple.com">

            <label for="atelier">Choisissez un atelier :</label>
            <select id="atelier" name="atelier" required>
                <option value="">-- Sélectionnez un créneau --</option>
                ${optionsHTML}
            </select>

            <button type="submit">Confirmer mon inscription</button>
        </form>
    </div>

    <script>
      document.addEventListener("DOMContentLoaded", function() {
        fetch('https://vps-308cfbf7.vps.ovh.net/webhook/api/ateliers/dispo')
          .then(response => response.json())
          .then(ateliers => {
            ateliers.forEach(atelier => {
              let option = document.querySelector(\`option[value="\${atelier.id_atelier}"]\`);
              if (option) {
                if (atelier.complet === true) {
                  option.innerText += " ⚠️ (Sur liste d'attente)";
                } else {
                  option.innerText += " ✅ (Disponible)";
                }
              }
            });
          })
          .catch(error => console.error('Erreur API dispo :', error));
      });
    </script>
</body>
</html>
`;

return { json: { html: html } };

